import { useEffect, useRef, useState } from 'react';
import Avatar from '../components/Avatar.jsx';
import Icon from '../components/Icon.jsx';
import PlanPanel from '../components/PlanPanel.jsx';
import useUserMedia from '../hooks/useUserMedia.js';
import ProviderChips from '../components/ProviderChips.jsx';
import { createVoiceAgent, VOICE_WANTS_AUDIO, IS_LIVE_VOICE, VOICE_PATH } from '../agents/index.js';
import { isSpeechMuted, setSpeechMuted, resolveVoiceName, onVoicesChanged } from '../agents/speech.js';
import { loadCapabilities, voiceCallProviders } from '../agents/providers.js';
import { VOICE_AGENT_URL } from '../config.js';
import { validateTriage } from '../contracts.js';

function fmt(sec) {
  return `${String(Math.floor(sec / 60)).padStart(2, '0')}:${String(sec % 60).padStart(2, '0')}`;
}

// Voice first. The camera and photos are optional extras the user can add any time.
export default function VoiceCall({ t, lang, triage, vet, insurance, onTriage, onCall, onEnd }) {
  const [consent, setConsent] = useState(false);
  const [toolResults, setToolResults] = useState([]);
  const [trace, setTrace] = useState([]);
  const [camOn, setCamOn] = useState(false);
  const [facing, setFacing] = useState('environment');
  const [micOn, setMicOn] = useState(!IS_LIVE_VOICE);
  const [soundOn, setSoundOn] = useState(!isSpeechMuted());
  const [aiLine, setAiLine] = useState('');
  const [userLine, setUserLine] = useState('');
  const [speaking, setSpeaking] = useState('none');
  const [listening, setListening] = useState(false);
  const [chips, setChips] = useState([]);
  const [draft, setDraft] = useState('');
  const [photos, setPhotos] = useState([]); // { url, received }
  const [error, setError] = useState('');
  const [sheetOpen, setSheetOpen] = useState(true);
  const [secs, setSecs] = useState(0);
  const [caps, setCaps] = useState(null);
  const [browser, setBrowser] = useState(() => resolveVoiceName(lang));

  const videoRef = useRef(null);
  const fileRef = useRef(null);
  const agentRef = useRef(null);
  const photoUrls = useRef([]);
  const onTriageRef = useRef(onTriage);
  onTriageRef.current = onTriage;

  const mic = useUserMedia({ enabled: VOICE_WANTS_AUDIO && consent && micOn, audio: true });
  const cam = useUserMedia({ enabled: camOn, video: true, facing });

  // ---- the conversation with Pawse
  useEffect(() => {
    if (IS_LIVE_VOICE && !consent) return;
    const agent = createVoiceAgent({ lang, shareWithGemini: consent });
    agentRef.current = agent;
    const off = agent.on((e) => {
      switch (e.type) {
        case 'transcript':
          if (e.role === 'ai') setAiLine(e.text);
          else setUserLine(e.text);
          break;
        case 'speaking':
          setSpeaking(e.who);
          break;
        case 'listening':
          setListening(e.on);
          break;
        case 'suggestions':
          setChips(e.items || []);
          break;
        case 'image_received':
          setPhotos((p) => p.map((x, i) => (i === p.length - 1 ? { ...x, received: true } : x)));
          break;
        case 'tool_result': setToolResults(p => [...p.slice(-4), e]); break;
        case 'agents': setTrace(e.trace); break;
        case 'triage': {
          const problems = validateTriage(e);
          if (problems.length) console.warn('[Pawse] triage violates the contract:', problems, e);
          onTriageRef.current(e);
          setSheetOpen(true);
          break;
        }
        case 'error':
          setError(e.message || '');
          break;
        default:
          break;
      }
    });
    agent.setMicMuted(!micOn);
    agent.setOutputMuted?.(!soundOn);
    agent.start();
    return () => {
      off();
      agent.end();
    };
  }, [lang, consent]);

  // ---- which AI runs this call (model ids come from the backend, never hardcoded)
  useEffect(() => {
    let alive = true;
    if (IS_LIVE_VOICE) loadCapabilities(VOICE_AGENT_URL || '').then((c) => alive && setCaps(c));
    const refresh = () => setBrowser(resolveVoiceName(lang));
    refresh();
    const off = onVoicesChanged(refresh);
    return () => {
      alive = false;
      off();
    };
  }, [lang]);

  // ---- media → <video> and → agent
  useEffect(() => {
    if (videoRef.current) videoRef.current.srcObject = cam.stream || null;
  }, [cam.stream, camOn]);

  useEffect(() => {
    agentRef.current && agentRef.current.attachMedia({ audio: mic.stream || null, video: cam.stream || null });
  }, [mic.stream, cam.stream]);

  useEffect(() => {
    const id = setInterval(() => setSecs((s) => s + 1), 1000);
    return () => clearInterval(id);
  }, []);

  useEffect(
    () => () => {
      photoUrls.current.forEach((u) => URL.revokeObjectURL(u));
    },
    []
  );

  // keep the screen awake during the call (best effort)
  useEffect(() => {
    let lock = null;
    (async () => {
      try {
        if ('wakeLock' in navigator) lock = await navigator.wakeLock.request('screen');
      } catch {
        /* not available */
      }
    })();
    return () => {
      try {
        lock && lock.release();
      } catch {
        /* ignore */
      }
    };
  }, []);

  const send = (text) => {
    const s = String(text || '').trim();
    if (!s) return;
    agentRef.current && agentRef.current.sendText(s);
    setDraft('');
  };

  const onPhoto = (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = '';
    if (!file) return;
    const url = URL.createObjectURL(file);
    photoUrls.current.push(url);
    setPhotos((p) => [...p, { url, received: false }]);
    agentRef.current && agentRef.current.sendImage(file);
  };

  const toggleMic = () => {
    const next = !micOn;
    setMicOn(next);
    agentRef.current && agentRef.current.setMicMuted(!next);
  };

  const toggleSound = () => {
    const next = !soundOn;
    setSoundOn(next);
    setSpeechMuted(!next);
    agentRef.current?.setOutputMuted?.(!next);
  };

  const status = listening ? null : speaking === 'ai' ? t.aiSpeaking : aiLine ? '' : t.connecting;
  const sheetVisible = triage && sheetOpen;
  const lastPhoto = photos[photos.length - 1];

  return (
    <main className="vcall">
      {IS_LIVE_VOICE && !consent && <section className="card">
        <p>Share your messages, selected photos and recorded speech with Gemini for care guidance. Gemini Live returns native audio. Camera video is a local preview only. Enable your microphone after starting; headphones help prevent echo.</p>
        <button className="btn primary" onClick={() => setConsent(true)}>Agree and start</button>
        <button className="btn ghost" onClick={onEnd}>Back</button>
      </section>}
      {toolResults.map((result,i) => <details className="card" key={i}><summary>{result.name}</summary>
        {result.ui.lines?.map((line,j)=><p key={j}>{line.german}<br/>{line.subtitle}</p>)}
        {result.ui.evidence?.map(e=><p key={e.evidence_id}>Demo policy · {e.title} · {e.section}: {e.snippet}</p>)}
        {result.ui.action === 'confirm_call' && /^tel:\+[1-9]\d{6,14}$/.test(result.ui.call_url || '') && <p>No call placed. <a href={result.ui.call_url}>Open device dialer for {result.ui.clinic_name}</a></p>}
      </details>)}
      {trace.length > 0 && <details className="card"><summary>Agent results</summary>{trace.map(x => <p key={x.agent_id}>{x.agent_id}: {x.state} — {x.detail}</p>)}</details>}
      <div className="vcall-top">
        <span className="timer-pill">
          <span className="rec-dot" aria-hidden="true" /> {fmt(secs)}
        </span>
        {triage && <span className={`top-level level-${triage.level}`}>{triage.headline || t.levels[triage.level]}</span>}
        <button type="button" className="round-btn" onClick={toggleSound} aria-pressed={!soundOn} aria-label={t.sound} title={t.sound}>
          <Icon name={soundOn ? 'volume' : 'volumeOff'} size={20} />
        </button>
      </div>

      <section className="stage">
        {camOn ? (
          <div className="cam-card">
            {cam.stream ? (
              <video ref={videoRef} className={facing === 'user' ? 'mirror' : ''} autoPlay playsInline muted />
            ) : (
              <div className="cam-msg">
                <Icon name="videoOff" size={28} />
                <span>{cam.error ? t.camUnavailable : t.camOpening}</span>
              </div>
            )}
            <div className={`cam-pip ${speaking === 'ai' ? 'talking' : ''}`}>
              <Avatar size={52} speaking={speaking === 'ai'} listening={listening} />
            </div>
            <div className="cam-tools">
              <button type="button" className="cam-tool" onClick={() => setFacing((f) => (f === 'user' ? 'environment' : 'user'))} aria-label={t.flip} disabled={!cam.stream}>
                <Icon name="flip" size={18} />
              </button>
              <button type="button" className="cam-tool" onClick={() => setCamOn(false)} aria-label={t.closeCamera}>
                <Icon name="x" size={18} />
              </button>
            </div>
          </div>
        ) : (
          <div className={`avatar-stage ${speaking === 'ai' ? 'talking' : ''} ${listening ? 'listening' : ''}`}>
            <span className="halo h1" aria-hidden="true" />
            <span className="halo h2" aria-hidden="true" />
            <Avatar size={168} speaking={speaking === 'ai'} listening={listening} />
          </div>
        )}
        <p className="stage-name">Pawse</p>
        <ProviderChips t={t} items={voiceCallProviders({ path: VOICE_PATH, caps, browser, muted: !soundOn })} />
        <p className="stage-status" aria-live="polite">
          {listening ? (
            <span className="listening-label">
              <span className="dots" aria-hidden="true">
                <i />
                <i />
                <i />
              </span>
              {t.listening}
            </span>
          ) : (
            status
          )}
        </p>
      </section>

      {!sheetVisible && (
        <div className="vcall-bottom">
          <div className="captions" aria-live="polite">
            {userLine && <p className="cap-user">{userLine}</p>}
            {lastPhoto && (
              <div className="cap-photo">
                <img src={lastPhoto.url} alt={t.photoSent} />
                <span>{lastPhoto.received ? `✓ ${t.photoSent}` : '…'}</span>
              </div>
            )}
            {aiLine && <p className="cap-ai">{aiLine}</p>}
            {error && <p className="cap-error">{error}</p>}
            {VOICE_WANTS_AUDIO && mic.error && <p className="cap-error">{t.micUnavailable}</p>}
          </div>

          {chips.length > 0 && (
            <div className="kw-chips" role="group" aria-label="Suggestions">
              {chips.map((c) => (
                <button key={c} type="button" className="kw-chip" onClick={() => send(c)}>
                  {c}
                </button>
              ))}
            </div>
          )}

          <form
            className="type-bar"
            onSubmit={(e) => {
              e.preventDefault();
              send(draft);
            }}
          >
            <button type="button" className="type-icon" onClick={() => fileRef.current && fileRef.current.click()} aria-label={t.photo} title={t.photo}>
              <Icon name="camera" size={20} />
            </button>
            <input
              disabled={IS_LIVE_VOICE && !consent}
              maxLength={4000}
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              placeholder={t.typePlaceholder}
              aria-label={t.typePlaceholder}
              enterKeyHint="send"
            />
            <button type="submit" className="type-send" aria-label={t.send} disabled={!draft.trim()}>
              <Icon name="send" size={18} />
            </button>
          </form>
          <input ref={fileRef} type="file" accept="image/*" capture="environment" hidden onChange={onPhoto} />

          <nav className="call-controls" aria-label="Call controls">
            <button type="button" className={micOn ? 'ctl' : 'ctl off'} onClick={toggleMic} aria-pressed={!micOn} aria-label={t.mic}>
              <Icon name={micOn ? 'mic' : 'micOff'} size={26} />
            </button>
            <button type="button" className="ctl hang" onClick={onEnd} aria-label={t.hangup}>
              <Icon name="phone" size={28} style={{ transform: 'rotate(135deg)' }} />
            </button>
            <button type="button" className={camOn ? 'ctl on' : 'ctl'} onClick={() => setCamOn((v) => !v)} aria-pressed={camOn} aria-label={t.camera}>
              <Icon name={camOn ? 'video' : 'videoOff'} size={26} />
            </button>
          </nav>
        </div>
      )}

      {triage && !sheetOpen && (
        <button type="button" className="reopen" onClick={() => setSheetOpen(true)}>
          <Icon name="chevronUp" size={18} /> {t.viewAdvice}
        </button>
      )}

      {sheetVisible && (
        <div className="sheet" role="dialog" aria-label={t.adviceTitle}>
          <div className="sheet-grab" aria-hidden="true" />
          <PlanPanel t={t} triage={triage} vet={vet} insurance={insurance} onCall={onCall} />
          <div className="sheet-foot">
            <button type="button" className="btn ghost" onClick={() => setSheetOpen(false)}>
              {t.keepTalking}
            </button>
            <button type="button" className="btn soft" onClick={onEnd}>
              {t.done}
            </button>
          </div>
        </div>
      )}
    </main>
  );
}
// Tiny wrapper around the browser's built-in text-to-speech, used ONLY by the mock agents
// so the demo actually talks. The live agents play their own audio.

const hasTTS = () =>
  typeof window !== 'undefined' && 'speechSynthesis' in window && typeof SpeechSynthesisUtterance !== 'undefined';

let muted = false;
try {
  muted = localStorage.getItem('pawse.muted') === '1';
} catch {
  /* storage unavailable */
}

export const isSpeechMuted = () => muted;

export function setSpeechMuted(m) {
  muted = !!m;
  try {
    localStorage.setItem('pawse.muted', muted ? '1' : '0');
  } catch {
    /* ignore */
  }
  if (muted && hasTTS()) window.speechSynthesis.cancel();
}

/** Rough spoken duration, used for pacing when the voice is muted or unavailable. */
export function estimateMs(text, lang) {
  const per = String(lang).startsWith('zh') ? 210 : 68;
  return Math.max(1200, String(text).length * per);
}

const TAGS = { zh: 'zh-CN', en: 'en-US', de: 'de-DE', hi: 'hi-IN' };

function pickVoice(tag) {
  const voices = window.speechSynthesis.getVoices();
  return voices.find((v) => v.lang === tag) || voices.find((v) => v.lang.toLowerCase().startsWith(tag.slice(0, 2)));
}

/** Which browser voice would speak `lang` (null name = the browser default). Used for the "powered by" badge. */
export function resolveVoiceName(lang) {
  if (!hasTTS()) return { available: false, name: null };
  const v = pickVoice(TAGS[lang] || lang);
  return { available: true, name: v ? v.name : null };
}

const voiceListeners = new Set();
/** Subscribe to the voice list becoming available (Chrome loads it late). Returns an unsubscribe. */
export function onVoicesChanged(cb) {
  voiceListeners.add(cb);
  if (hasTTS() && voiceListeners.size === 1) window.speechSynthesis.onvoiceschanged = () => voiceListeners.forEach((l) => l());
  return () => voiceListeners.delete(cb);
}

/** Call inside a tap so iOS Safari allows speech later on. */
export function primeSpeech() {
  if (!hasTTS()) return;
  try {
    const u = new SpeechSynthesisUtterance(' ');
    u.volume = 0;
    window.speechSynthesis.speak(u);
  } catch {
    /* ignore */
  }
}

export function stopSpeech() {
  if (hasTTS()) window.speechSynthesis.cancel();
}

/**
 * Speak `text`; resolves when finished. speed > 1 (tests / rehearsal) skips the voice.
 * silent: don't play it, just wait as long as it would take (a call running in the background).
 */
export function speak(text, lang, { speed = 1, pitch = 1, rate = 1, silent = false } = {}) {
  const est = estimateMs(text, lang);
  if (speed > 1 || silent || muted || !hasTTS()) return new Promise((r) => setTimeout(r, est / speed));

  return new Promise((resolve) => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      clearTimeout(guard);
      resolve();
    };
    const guard = setTimeout(finish, est * 2 + 3000); // never hang if the engine stalls
    try {
      const u = new SpeechSynthesisUtterance(text);
      const tag = TAGS[lang] || lang;
      u.lang = tag;
      const v = pickVoice(tag);
      if (v) u.voice = v;
      u.pitch = pitch;
      u.rate = rate;
      u.onend = finish;
      u.onerror = finish;
      window.speechSynthesis.speak(u);
    } catch {
      setTimeout(finish, est);
    }
  });
}
import { useEffect, useState } from 'react';

/**
 * Opens the camera and/or microphone while `enabled`.
 * Returns { stream, error } – error is set when the device can't be opened
 * (no device, permission denied, or plain http on a phone).
 */
export default function useUserMedia({ enabled = true, video = false, audio = false, facing = 'environment' } = {}) {
  const [stream, setStream] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!enabled || (!video && !audio)) {
      setStream(null);
      setError(null);
      return undefined;
    }
    const md = typeof navigator !== 'undefined' ? navigator.mediaDevices : null;
    if (!md || !md.getUserMedia) {
      setError('unsupported');
      return undefined;
    }

    let cancelled = false;
    let current = null;
    setError(null);
    md.getUserMedia({ video: video ? { facingMode: { ideal: facing } } : false, audio })
      .then((s) => {
        if (cancelled) {
          s.getTracks().forEach((tr) => tr.stop());
          return;
        }
        current = s;
        setStream(s);
      })
      .catch((e) => {
        if (!cancelled) setError(e && e.name ? e.name : 'error');
      });

    return () => {
      cancelled = true;
      if (current) current.getTracks().forEach((tr) => tr.stop());
      setStream(null);
    };
  }, [enabled, video, audio, facing]);

  return { stream, error };
}

// SLOT 1: live voice agent, turn-based over the same-origin Pawse REST API.
//   mic -> (silence detection) -> WAV -> POST /api/v1/voice/transcriptions -> user transcript
//   text -> POST /api/v1/care/requests (non-stream JSON) -> triage event + spoken verdict
// Implements the VOICE AGENT contract in ../contracts.js. Browser APIs are looked up lazily so the
// module also loads (and is testable) in plain Node.

import { VOICE_AGENT_URL } from '../config.js';
import { speak, stopSpeech } from './speech.js';

const T = {
  en: {
    greet: "Hi, I'm Pawse. Tell me what's going on with your cat. You can also send a photo.",
    chips: ['Limping', 'Not eating', 'Vomiting', 'Breathing fast'],
    headline: { red: 'See an emergency vet now', yellow: 'Contact a vet today', green: 'Keep watching' },
    fallbackStep: 'Call a veterinarian and describe what you see.',
    noSpeech: "I couldn't make out what you said. Please try again or type it.",
    errTranscribe: 'Could not transcribe your voice. Please try again or type your message.',
    errCare: 'Could not get advice right now. Please try again in a moment.',
    errPhoto: 'This photo type is not supported. Use JPEG, PNG or WebP.',
    errMic: 'Microphone recording is not available. You can type instead.',
    ownerLabel: 'Owner',
  },
  zh: {
    greet: '你好，我是 Pawse。请告诉我你的猫怎么了，也可以发一张照片。',
    chips: ['一瘸一拐', '不吃东西', '呕吐', '呼吸急促'],
    headline: { red: '请立即去急诊', yellow: '今天联系兽医', green: '继续观察' },
    fallbackStep: '联系兽医并说明你看到的情况。',
    noSpeech: '我没听清，请再说一次或直接打字。',
    errTranscribe: '语音识别失败，请重试或直接打字。',
    errCare: '暂时无法给出建议，请稍后再试。',
    errPhoto: '不支持这种照片格式，请使用 JPEG、PNG 或 WebP。',
    errMic: '无法录音，你可以直接打字。',
    ownerLabel: '主人',
  },
};

const SILENCE_MS = 1500;
const SPEECH_RMS = 0.02;
const MIN_SPEECH_MS = 400;
const MAX_TURN_MS = 30000;
const PHOTO_TYPES = ['image/jpeg', 'image/png', 'image/webp'];

/** Backend urgency -> UI level. Never "green": the backend cannot rule out an emergency. */
export function urgencyToLevel(urgency) {
  return urgency === 'emergency' ? 'red' : 'yellow';
}

export function mapCareResult(res, lang = 'en') {
  const t = T[lang] || T.en;
  const a = (res && res.assessment) || {};
  const level = urgencyToLevel(a.urgency);
  const steps = [...(a.questions || []), ...(a.services_to_ask_about || [])].filter(Boolean);
  if (!steps.length) steps.push(t.fallbackStep);
  const out = {
    type: 'triage',
    level,
    headline: t.headline[level],
    steps,
    summary: a.summary || (res && res.handoff) || t.headline[level],
  };
  if (level === 'red') out.escalation = a.summary || t.headline.red;
  return out;
}

function encodeWav(samples, rate) {
  const buf = new ArrayBuffer(44 + samples.length * 2);
  const v = new DataView(buf);
  const w = (o, s) => [...s].forEach((c, i) => v.setUint8(o + i, c.charCodeAt(0)));
  w(0, 'RIFF'); v.setUint32(4, 36 + samples.length * 2, true); w(8, 'WAVE'); w(12, 'fmt ');
  v.setUint32(16, 16, true); v.setUint16(20, 1, true); v.setUint16(22, 1, true);
  v.setUint32(24, rate, true); v.setUint32(28, rate * 2, true); v.setUint16(32, 2, true); v.setUint16(34, 16, true);
  w(36, 'data'); v.setUint32(40, samples.length * 2, true);
  for (let i = 0; i < samples.length; i++) {
    const s = Math.max(-1, Math.min(1, samples[i]));
    v.setInt16(44 + i * 2, s < 0 ? s * 0x8000 : s * 0x7fff, true);
  }
  return new Uint8Array(buf);
}

function toBase64(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(s);
}

/** Recorded Blob (webm/mp4/...) -> base64 mono 16 kHz 16-bit WAV. Returns null if under 0.5 s. */
export async function blobToWavBase64(blob) {
  const AC = globalThis.AudioContext || globalThis.webkitAudioContext;
  const ctx = new AC();
  try {
    const decoded = await ctx.decodeAudioData(await blob.arrayBuffer());
    const rate = 16000;
    const off = new OfflineAudioContext(1, Math.max(1, Math.ceil(decoded.duration * rate)), rate);
    const src = off.createBufferSource();
    src.buffer = decoded;
    src.connect(off.destination);
    src.start();
    const rendered = await off.startRendering();
    const pcm = rendered.getChannelData(0);
    if (pcm.length < rate * 0.5) return null;
    return toBase64(encodeWav(pcm.subarray(0, rate * 59), rate));
  } finally {
    try { ctx.close(); } catch { /* ignore */ }
  }
}

function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(String(r.result).split(',')[1] || '');
    r.onerror = () => reject(r.error);
    r.readAsDataURL(file);
  });
}

export function createLiveVoiceAgent({ lang = 'en', shareWithGemini = false } = {}) {
  const t = T[lang] || T.en;
  const apiLang = ['en', 'zh', 'de', 'hi'].includes(lang) ? lang : 'en';
  const base = (VOICE_AGENT_URL || '').replace(/\/$/, '');
  const listeners = new Set();
  const userTurns = [];
  let started = false;
  let ended = false;
  let muted = false;
  let aiSpeaking = false;
  let photo = null; // { mime_type, data }
  let queue = Promise.resolve();
  let stream = null;
  let recorder = null;
  let chunks = [];
  let audioCtx = null;
  let poll = null;
  let heardMs = 0;
  let silentMs = 0;
  let turnMs = 0;

  const emit = (e) => {
    if (ended && e.type !== 'ended') return;
    listeners.forEach((l) => {
      try { l(e); } catch { /* a bad listener must not break the call */ }
    });
  };
  const fail = (message) => emit({ type: 'error', message });

  async function api(path, body) {
    if (ended || !shareWithGemini) throw new Error('Confirm sharing with Gemini before continuing.');
    const ctl = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const timer = ctl && setTimeout(() => ctl.abort(), 60000);
    try {
      const res = await fetch(`${base}${path}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
        signal: ctl ? ctl.signal : undefined,
      });
      if (!res.ok) {
        let detail = '';
        try { const j = await res.json(); detail = typeof j.detail === 'string' ? j.detail : ''; } catch { /* ignore */ }
        throw new Error(detail || `HTTP ${res.status}`);
      }
      return await res.json();
    } finally {
      if (timer) clearTimeout(timer);
    }
  }

  async function say(text) {
    if (ended) return;
    aiSpeaking = true;
    finishTurn(false);
    emit({ type: 'listening', on: false });
    emit({ type: 'speaking', who: 'ai' });
    emit({ type: 'transcript', role: 'ai', text });
    try { await speak(text, lang); } catch { /* speech is best effort */ }
    aiSpeaking = false;
    if (ended) return;
    emit({ type: 'speaking', who: 'none' });
    emit({ type: 'listening', on: !muted });
    resetTurn();
  }

  async function advise() {
    const query = userTurns.join('\n');
    if (query.length > 4000) { fail('Conversation exceeds 4,000 characters. Start a new summary.'); return; }
    const body = { query, language: apiLang, share_with_ai: true };
    if (photo) body.photo = photo;
    let res;
    try {
      const run = await api('/api/v1/agents/runs', { care: body });
      res = run.care;
      emit({ type: 'agents', trace: run.trace || [], actions: run.actions || [] });
    } catch (err) {
      fail(`${t.errCare} (${err.message})`);
      emit({ type: 'listening', on: !muted });
      return;
    }
    if (ended) return;
    const triage = mapCareResult(res, lang);
    emit(triage);
    await say(triage.summary);
  }

  const enqueue = (fn) => {
    queue = queue.then(fn).catch((err) => fail(String(err && err.message || err)));
    return queue;
  };

  function takeUserText(text) {
    userTurns.push(text);
    emit({ type: 'speaking', who: 'user' });
    emit({ type: 'transcript', role: 'user', text });
    emit({ type: 'suggestions', items: [] });
    emit({ type: 'speaking', who: 'none' });
    return advise();
  }

  async function transcribe(blob) {
    let wav;
    try {
      wav = await blobToWavBase64(blob);
    } catch {
      fail(t.errTranscribe);
      return;
    }
    if (!wav || ended) return;
    let out;
    try {
      out = await api('/api/v1/voice/transcriptions', { audio: { data: wav }, language: apiLang, share_with_gemini: true });
    } catch (err) {
      fail(`${t.errTranscribe} (${err.message})`);
      return;
    }
    if (ended) return;
    const text = String((out && out.text) || '').trim();
    if (!text) { fail(t.noSpeech); return; }
    await takeUserText(text);
  }

  // --- recording with silence detection -----------------------------------------------------
  function resetTurn() {
    heardMs = 0; silentMs = 0; turnMs = 0;
    if (!recorder || recorder.state === 'inactive') startRecorder();
  }

  function startRecorder() {
    if (!stream || ended || muted || aiSpeaking) return;
    chunks = [];
    heardMs = 0; silentMs = 0; turnMs = 0;
    try {
      recorder = new MediaRecorder(new MediaStream(stream.getAudioTracks()));
    } catch {
      fail(t.errMic);
      return;
    }
    const rec = recorder;
    rec.ondataavailable = (e) => { if (e.data && e.data.size) chunks.push(e.data); };
    rec.onstop = () => {
      const keep = rec.keepTurn;
      const blob = new Blob(chunks, { type: rec.mimeType || 'audio/webm' });
      chunks = [];
      if (keep && !ended) enqueue(() => transcribe(blob));
      if (!ended && recorder === rec) startRecorder();
    };
    rec.start();
  }

  function finishTurn(keep) {
    if (!recorder || recorder.state !== 'recording') return;
    recorder.keepTurn = keep;
    emit({ type: 'speaking', who: 'none' });
    try { recorder.stop(); } catch { /* ignore */ }
  }

  function tick(analyser, buf, step) {
    if (ended) return;
    if (muted || aiSpeaking) { heardMs = 0; silentMs = 0; turnMs = 0; return; }
    analyser.getFloatTimeDomainData(buf);
    let sum = 0;
    for (let i = 0; i < buf.length; i++) sum += buf[i] * buf[i];
    const loud = Math.sqrt(sum / buf.length) > SPEECH_RMS;
    if (loud) {
      if (heardMs === 0) emit({ type: 'speaking', who: 'user' });
      heardMs += step; silentMs = 0;
    } else if (heardMs > 0) {
      silentMs += step;
    }
    turnMs += step;
    if (heardMs >= MIN_SPEECH_MS && (silentMs >= SILENCE_MS || turnMs >= MAX_TURN_MS)) {
      finishTurn(true);
    } else if (heardMs === 0 && turnMs >= 10000) {
      finishTurn(false); // nothing said: recycle the recorder, discard
    } else if (heardMs > 0 && heardMs < MIN_SPEECH_MS && silentMs >= SILENCE_MS) {
      finishTurn(false); // a click or cough
    }
  }

  function stopRecording() {
    if (poll) { clearInterval(poll); poll = null; }
    if (recorder) {
      recorder.keepTurn = false;
      try { if (recorder.state !== 'inactive') recorder.stop(); } catch { /* ignore */ }
      recorder = null;
    }
    try { audioCtx && audioCtx.close(); } catch { /* ignore */ }
    audioCtx = null;
  }

  return {
    wantsAudio: true,
    on(cb) {
      listeners.add(cb);
      return () => listeners.delete(cb);
    },
    start() {
      if (started || ended) return;
      if (!shareWithGemini) { fail('Confirm sharing with Gemini before continuing.'); return; }
      started = true;
      enqueue(async () => {
        emit({ type: 'suggestions', items: t.chips });
        await say(t.greet);
        emit({ type: 'listening', on: !muted });
      });
    },
    end() {
      if (ended) return;
      stopRecording();
      stopSpeech();
      if (stream) { try { stream.getTracks().forEach((tr) => tr.stop()); } catch { /* ignore */ } }
      stream = null;
      ended = true;
      listeners.forEach((l) => { try { l({ type: 'ended' }); } catch { /* ignore */ } });
    },
    sendText(text) {
      const s = String(text || '').trim();
      if (!s || ended || !shareWithGemini) return;
      stopSpeech();
      aiSpeaking = false;
      enqueue(() => takeUserText(s));
    },
    async sendImage(file) {
      if (ended || !file || !shareWithGemini) return;
      if (file.size > 3000000) { fail('Use an image up to 3 MB.'); return; }
      const mime = file.type;
      if (!PHOTO_TYPES.includes(mime)) { fail(t.errPhoto); return; }
      try {
        photo = { mime_type: mime, data: await fileToBase64(file) };
      } catch {
        fail(t.errPhoto);
        return;
      }
      emit({ type: 'image_received' });
    },
    attachMedia({ audio } = {}) {
      if (!audio) { stopRecording(); stream = null; return; }
      if (ended || !shareWithGemini || audio === stream) return;
      stopRecording();
      stream = audio;
      const AC = globalThis.AudioContext || globalThis.webkitAudioContext;
      if (!AC || typeof MediaRecorder === 'undefined') { fail(t.errMic); return; }
      try {
        audioCtx = new AC();
        const analyser = audioCtx.createAnalyser();
        analyser.fftSize = 1024;
        audioCtx.createMediaStreamSource(audio).connect(analyser);
        const buf = new Float32Array(analyser.fftSize);
        startRecorder();
        poll = setInterval(() => tick(analyser, buf, 100), 100);
      } catch {
        fail(t.errMic);
      }
    },
    setMicMuted(m) {
      muted = !!m;
      if (!started || ended) return;
      emit({ type: 'listening', on: !muted && !aiSpeaking });
      if (muted) finishTurn(false);
      else resetTurn();
    },
  };
}
import { VOICE_AGENT, CLINIC_SEARCH, PHONE_AGENT, MOCK_SPEED } from '../config.js';
import { createMockVoiceAgent } from './mockVoiceAgent.js';
import { createGeminiLiveAgent } from './geminiLiveAgent.js';
import { createLiveVoiceAgent } from './liveVoiceAgent.js';
import { mockSearchClinics } from './mockClinicSearch.js';
import { liveSearchClinics } from './liveClinicSearch.js';
import { createMockPhoneCall } from './mockPhoneAgent.js';
import { createLivePhoneCall } from './livePhoneAgent.js';

export const IS_LIVE_VOICE = VOICE_AGENT === 'live';
export const IS_LIVE_CLINICS = CLINIC_SEARCH === 'live';
export const IS_LIVE_PHONE = PHONE_AGENT === 'live';
export const IS_MOCK = !IS_LIVE_VOICE || !IS_LIVE_CLINICS || !IS_LIVE_PHONE;

/** Which voice path runs: 'mock' (scripted), 'rest' (transcribe + care over REST) or 'native' (Gemini Live audio). */
export const VOICE_PATH = !IS_LIVE_VOICE ? 'mock' : new URLSearchParams(globalThis.location?.search || '').get('voice') === 'rest' ? 'rest' : 'native';

/** The page opens the microphone only if the active voice agent wants audio. */
export const VOICE_WANTS_AUDIO = IS_LIVE_VOICE;

/** 1. Voice conversation with Pawse. */
export function createVoiceAgent(opts) {
  return IS_LIVE_VOICE ? (new URLSearchParams(globalThis.location?.search || '').get('voice') === 'rest' ? createLiveVoiceAgent(opts) : createGeminiLiveAgent(opts)) : createMockVoiceAgent({ speed: MOCK_SPEED, ...opts });
}

/** 2. Nearby vet clinics. */
export function searchClinics(opts) {
  return IS_LIVE_CLINICS ? liveSearchClinics(opts) : mockSearchClinics({ speed: MOCK_SPEED, ...opts });
}

/** 3. Pawse calls the clinic or the insurer. */
export function createPhoneCall(opts) {
  return IS_LIVE_PHONE ? createLivePhoneCall(opts) : createMockPhoneCall({ speed: MOCK_SPEED, ...opts });
}
// Central switches. Set them in .env.local (see .env.example).
// import.meta.env is undefined outside Vite (e.g. plain-Node checks), so guard it.
const env = (typeof import.meta !== 'undefined' && import.meta.env) || {};

const param = (k) => {
  try {
    return new URLSearchParams(window.location.search).get(k);
  } catch {
    return null;
  }
};

/** 'mock' = scripted demo (default). 'live' = the Pawse backend. "?live=1" in the URL switches all three at runtime. */
const DEMO_ALL = param('demo') === '1';
const LIVE_ALL = !DEMO_ALL && param('live') === '1';
export const VOICE_AGENT = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_VOICE_AGENT || 'mock';
export const CLINIC_SEARCH = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_CLINIC_SEARCH || 'mock';
export const PHONE_AGENT = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_PHONE_AGENT || 'mock';

export const VOICE_AGENT_URL = env.VITE_VOICE_AGENT_URL || '';
export const CLINIC_SEARCH_URL = env.VITE_CLINIC_SEARCH_URL || '';
export const PHONE_AGENT_URL = env.VITE_PHONE_AGENT_URL || '';

/** Mock playback speed. "?speed=3" in the URL plays the demo 3x faster (handy for rehearsing). */
export const MOCK_SPEED = (() => {
  const v = Number(param('speed'));
  return v > 0 ? v : 1;
})();

import { GoogleGenAI } from '@google/genai';
import { VOICE_AGENT_URL } from '../config.js';
import { mapCareResult } from './liveVoiceAgent.js';
import { createNativeAudio } from './nativeAudio.js';

// Injectable transport/audio factories keep protocol tests offline and deterministic.
export function createGeminiLiveAgent({lang='en',shareWithGemini=false,
  clientFactory=options=>new GoogleGenAI(options), audioFactory=createNativeAudio}={}) {
  const listeners=new Set(), pending=new Set(), toolIds=new Set(), cancelledTools=new Set();
  let started=false, ended=false, session=null, audio=null, media=null, muted=true, outputMuted=false, timer=null;
  let audioEpoch=0;
  let inputText='',outputText='', playback=Promise.resolve();
  const emit=e=>{if(!ended||e.type==='ended') for(const fn of listeners){try{fn(e);}catch{}}};
  const error=message=>emit({type:'error',message});
  async function post(path,body){
    const ctl=new AbortController();pending.add(ctl);const timeout=setTimeout(()=>ctl.abort(),55000);
    try{
      const r=await fetch(`${VOICE_AGENT_URL || ''}/api/v1/live/${path}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:ctl.signal});
      if(!r.ok){const j=await r.json().catch(()=>({}));throw Error(typeof j.detail==='string'?j.detail:`Live request failed (${r.status})`);}
      return await r.json();
    }finally{clearTimeout(timeout);pending.delete(ctl);}
  }
  function end(){
    if(ended)return;ended=true;clearTimeout(timer);
    for(const c of pending)c.abort();pending.clear();
    try{session?.close();}catch{}session=null;
    media?.getTracks().forEach(t=>t.stop());media=null;
    audio?.close().catch(()=>{});emit({type:'ended'});
  }
  function send(payload){if(!ended&&session)session.sendRealtimeInput(payload);}
  async function tool(call){
    if(!call.id||toolIds.has(call.id)||ended)return;
    toolIds.add(call.id);
    if(toolIds.size>100){error('Session tool limit reached. Start a new session.');end();return;}
    emit({type:'tool_status',name:call.name,state:'running'});
    let response;
    try{
      const result=await post('tool-calls',{id:call.id,name:call.name,args:call.args||{},share_with_gemini:true,context:{language:lang,share_location:false}});
      response=result.response;
      if(ended||cancelledTools.has(call.id))return;
      const ui=result.ui;
      if(ui?.care){emit({type:'agents',trace:ui.trace||[],actions:[]});emit(mapCareResult(ui.care,lang));}
      else if(ui)emit({type:'tool_result',name:call.name,ui});
    }catch(e){response={error:'tool_unavailable',detail:e.message};}
    if(!ended&&!cancelledTools.has(call.id)&&session){
      session.sendToolResponse({functionResponses:[{id:call.id,name:call.name,response}]});
      emit({type:'tool_status',name:call.name,state:response?.error?'unavailable':'complete'});
    }
  }
  function message(msg){
    if(ended)return;
    try{
      for(const id of msg.toolCallCancellation?.ids||[])cancelledTools.add(id);
      const c=msg.serverContent;
      if(c?.interrupted){audioEpoch++;audio.flush();inputText='';outputText='';}
      if(c?.inputTranscription?.text){inputText+=c.inputTranscription.text;emit({type:'transcript',role:'user',text:inputText});}
      if(c?.outputTranscription?.text){outputText+=c.outputTranscription.text;emit({type:'transcript',role:'ai',text:outputText});}
      for(const part of c?.modelTurn?.parts||[]){
        const data=part.inlineData;
        if(data?.data&&data.mimeType?.startsWith('audio/pcm')){
          const rate=Number(/rate=(\d+)/.exec(data.mimeType)?.[1]||24000);
          const epoch=audioEpoch;
          playback=playback.then(()=>{if(!ended && epoch===audioEpoch)return audio.play(data.data,rate);}).catch(()=>{error('Native audio playback failed. Restart the session.');end();});
        }
      }
      if(c?.turnComplete){inputText='';outputText='';emit({type:'listening',on:!muted});}
      for(const call of msg.toolCall?.functionCalls||[]) void tool(call).catch(()=>error('Tool response could not be delivered.'));
      if(msg.goAway){error('Live session is ending. Start a new conversation.');end();}
    }catch{error('Live response could not be processed.');end();}
  }
  return {
    wantsAudio:true,on(fn){listeners.add(fn);return()=>listeners.delete(fn);},
    async start(){
      if(started||ended)return;
      if(!shareWithGemini){error('Confirm sharing with Gemini before starting.');return;}
      started=true;
      try{
        audio=audioFactory(frame=>{if(!muted&&session&&!ended)send({audio:{data:frame,mimeType:'audio/pcm;rate=16000'}});}, speaking=>emit({type:'speaking',who:speaking?'ai':'none'}));
        audio.setMuted(outputMuted);
        const token=await post('tokens',{language:lang,share_with_gemini:true});if(ended)return;
        const ai=clientFactory({apiKey:token.token,httpOptions:{apiVersion:token.api_version}});
        const connected=await ai.live.connect({model:token.model,config:{responseModalities:['AUDIO']},callbacks:{onmessage:message,onerror:()=>{error('Gemini Live connection failed. Restart or use text fallback.');end();},onclose:()=>{if(!ended){error('Gemini Live disconnected. Start a new session.');end();}}}});
        if(ended){connected.close();return;}session=connected;
        timer=setTimeout(()=>{error('Session time limit reached. Start a new conversation.');end();},8*60*1000);
        if(media&&!muted)await audio.attach(media);
        emit({type:'listening',on:!muted});
        send({text:'Introduce yourself briefly as Pawse, an AI cat-care assistant, and ask how you can help. Do not invent a concern.'});
      }catch(e){if(!ended){error(e.message?.includes('key')?'Live audio could not start. Check server configuration.':e.message||'Live audio could not start.');end();}}
    },
    end,
    sendText(text){if(!session){error('Wait for the Live connection, then try again.');return;}const s=String(text||'').trim();if(!s||s.length>4000)return;audio.flush();inputText='';outputText='';send({text:s});emit({type:'transcript',role:'user',text:s});},
    async sendImage(file){
